Die folgenden Smart Contract-Implementierungen in Ethereum-Solidity können als Grundlage für die oben genannten Phasen dienen:

1. Privater Verkauf

```solidity
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";

contract PrivateSale is ERC20 {
    address[] private _privateAddresses;
    mapping(address => uint256) private _balances;

    constructor(uint256 initialSupply) ERC20("Private Token", "PRV") {
        _mint(msg.sender, initialSupply);
    }

    function addPrivateAddress(address privateAddress) public {
        _privateAddresses.push(privateAddress);
    }

    function buyToken() public {
        require(
            _isPrivateAddress(msg.sender),
            "Private Sale: Caller is not a private address"
        );

        uint256 amount = _balances[msg.sender] + _msgValue();
        _balances[msg.sender] = amount;

        _mint(msg.sender, amount);
    }

    function _isPrivateAddress(address addr) internal view returns (bool) {
        for (uint256 I = 0; I < _privateAddresses.length; i++) {
            if (addr == _privateAddresses[i]) {
                return true;
            }
        }
        return false;
    }
}
```

