```cpp
#include <iostream>
#include <string>

#include <boost/algorithm/string.hpp>
#include <boost/regex.hpp>

#include "cmark/cmark.h"

std::string markdown_to_html(const std::string& markdown) {
  // Ein neues Dokument erzeugen
  cm_markdown_state *state = cm_markdown_new();

  // Die Markdown-Optionen festlegen
  cm_markdown_options options = {0};
  options.commonmark = 1;
  options.gfm = 1;
  options.smart = 1;
  options.html = 1;

  // Die Markdown-Quelle einfügen
  cm_markdown_parse_from_string(state, markdown.c_str(), markdown.length(), &options);

  // Eine neue HTML-Struktur erstellen
  cm_html_document *html = cm_html_new();

  // Die HTML-Optionen festlegen
  cm_html_options html_options = {0};
  html_options.smart = 1;
  html_options.unsafe = 0;

  // Die Markdown-Struktur in HTML konvertieren
  cm_html_render_html_document(html, state, &html_options);

  // Die HTML-Ausgabe extrahieren
  std::string html_output;
  char *html_str = cm_html_get_html(html);
  html_output.assign(html_str);
  cm_free(html_str);

  // Die HTML-Struktur freigeben
  cm_html_free(html);
  cm_markdown_free(state);

  // Die HTML-Ausgabe zurückgeben
  return html_output;
}

int main() {
  std::string markdown = "Hier ist ein **Beispiel** von Markdown, das in HTML konvertiert werden soll.";

  std::string html = markdown_to_html(markdown);

  std::cout << html << std::endl;

  return 0;
}
```

