        box-shadow: 0 0 10px rgba(0, 0, 0, 0.5);
      }

      .chat {
        list-style: none;
        margin: 0;
        padding: 0;
      }

      .chat li {
        padding: 10px;
        border-radius: 5px;
        margin-bottom: 10px;
        position: relative;
      }

      .chat .bot {
        background: #f2f2f2;
        color: #333;
      }

      .chat .user {
        background: #eee;
        color: #555;
      }

      .chat .bot:before,
      .chat .user:before {
        content: "";
        position: absolute;
        top: 50%;
        transform: translateY(-50%);
        border: 5px solid transparent;
      }

      .chat .bot:before {
        border-top-color: #f2f2f2;
        right: 100%;
