      }

      .chat .user:before {
        border-top-color: #eee;
        left: 100%;
        margin-left: 10px;
      }
    </style>
  </head>
  <body>
    <div id="modal" class="modal">
      <div class="modal-dialog">
        <ul id="chat" class="chat"></ul>
      </div>
    </div>
    <script>
      // Code für den Chatbot
      const botName = "Chatbot";
      let chatHistory = [];

      function addMessage(sender, message) {
        const newMessage = document.createElement("li");
        newMessage.classList.add(sender);
        newMessage.innerHTML = `<strong>${sender}: </strong>${message}`;
        document.querySelector("#chat").appendChild(newMessage);
      }

      function showChat() {
        document.querySelector("#modal").style.display = "block";
        for (let I = 0; I < chatHistory.length; i++) {
          const message = chatHistory[i];
          addMessage(message.sender, message.message);
        }
      }

      function hideChat() {
        document.querySelector("#modal").style.display = "none";
      }

      function sendMessage() {
        const message = document.getElementById("message").value;
        if (message) {
          chatHistory.push({ sender: "user", message });
          addMessage("user", message);
          document.getElementById("message").value = "";
          // Antwort des Chatbots
          const botResponse = `Ich verstehe. ${message} ist interessant. Ich werde das überprüfen.`
          chatHistory.push({ sender: "bot", message: botResponse });
          addMessage("bot", botResponse);
        }
      }

      document.getElementById("open-modal").addEventListener("click", showChat);
      document.getElementById("close-modal").addEventListener("click", hideChat);
      document.getElementById("send-message").addEventListener("click", sendMessage);
    </script>
    <button id="open-modal">Öffne Chat</button>
    <div id="message-container">
      <label for="message">Deine Nachricht:</label>
      <input type="text" id="message" />
      <button id="send-message">Senden</button>
      <button id="close-modal">Schließen</button>
    </div>
  </body>
</html>
