             </p>
             <p>
               Sie haben den Twitter-Namen "{session.user.username}".
             </p>
           </>
         )}
         {status === "loading" && <p>Loading...</p>}
       </div>
     );
   }
   ```

8. Fügen Sie den folgenden Code zu `pages/api/auth/callback/twitter.js` hinzu, um die Twitter-Authentifizierung abzuschließen:

   ```javascript
   import { NextResponse } from "next-auth/react";

   export default async (req, res) => {
     const response = await fetch(
       "https://api.twitter.com/2/users/by/username?usernames=" +
         req.query.handle,
       {
         headers: {
           Authorization: `Bearer ${req.cookies.__Secure-next-auth.sessionToken}`,
         },
       }
     );

     const user = await response.json();

     const { handle } = req.query;

     const tweet = await fetch(
       `https://api.twitter.com/2/tweets/search/recent?query=from%3A${handle}`,
       {
         headers: {
           Authorization: `Bearer ${req.cookies.__Secure-next-auth.sessionToken}`,
         },
       }
     );

     const data = await tweet.json();

     const { data: tweetData } = data;

     const tweetText = tweetData[0]?.text;

     const sentiment = await fetch(
       "https://api.meaningcloud.com/sentiment-2.1",
       {
         method: "POST",
         headers: {
           "Content-Type": "application/x-www-form-urlencoded",
           Authorization: `Bearer ${process.env.MEANING_CLOUD_API_KEY}`,
         },
         body: new URLSearchParams({
           lang: "en",
           txt: tweetText,
           key: process.env.MEANING_CLOUD_API_KEY,
           ip: "check",
         }),
       }
     );

     const sentimentData = await sentiment.json();

     const sentimentScore =
       sentimentData.score_tag === "pos"
         ? 1
         : sentimentData.score_tag === "neu"
         ? 0
         : -1;

     const responseToReturn = NextResponse.json({
       id: user.data[0].id,
       name: user.data[0].name,
