10. Erstellen Sie eine neue Komponente namens `TweetSentiment` in der Datei `components/TweetSentiment.js`, die das Sentiment des Tweets analysiert:

   ```javascript
   import { useState, useEffect } from "react";

   const TweetSentiment = ({ tweetText }) => {
     const [sentimentScore, setSentimentScore] = useState(0);

     useEffect(() => {
       async function getSentiment() {
         const response = await fetch(
           "https://api.meaningcloud.com/sentiment-2.1",
           {
             method: "POST",
             headers: {
               "Content-Type": "application/x-www-form-urlencoded",
               Authorization: `Bearer ${process.env.MEANING_CLOUD_API_KEY}`,
             },
             body: new URLSearchParams({
               lang: "en",
               txt: tweetText,
               key: process.env.MEANING_CLOUD_API_KEY,
               ip: "check",
             }),
           }
         );

         const sentimentData = await response.json();

         const sentimentScore =
           sentimentData.score_tag === "pos"
             ? 1
             : sentimentData.score_tag === "neu"
             ? 0
             : -1;

         setSentimentScore(sentimentScore);
       }

       getSentiment();
     }, [tweetText]);

     return sentimentScore;
   };

   export default TweetSentiment;
   ```

