         setTweetText(tweetData[0]?.text);
         setSentimentScore(TweetSentiment(tweetData[0]?.text));
       }

       if (session) {
         fetchTweet();
       }
     }, [session, handle]);

     return (
       <div className="flex flex-col items-center justify-center min-h-screen py-2">
