Hier ist ein C++-Programm, das eine Textdatei Zeile für Zeile liest und die Anzahl der Vorkommen eines bestimmten Wortes in der Datei zählt:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <unordered_map>

using namespace std;

int main()
{
    // Wort, das gesucht werden soll
    string suchwort = "C++";

    // Dateiname
    string dateiname = "beispiel.txt";

    // Anzahl der Vorkommen des gesuchten Wortes
    int anzahl = 0;

    // Hash-Tabellen zum Speichern von Worten und deren Vorkommen
    unordered_map<string, int> wort_zahl;

    // Öffnen der Datei
    ifstream datei(dateiname);

    if (!datei) {
        cout << "Fehler: Kann Datei " << dateiname << " nicht öffnen." << endl;
        return 1;
    }

    // Zeilen der Datei lesen und Wort zählen
    string zeile;
    while (getline(datei, zeile)) {
        istringstream stream(zeile);
        string wort;
        while (stream >> wort) {
            if (wort == suchwort) {
                anzahl++;
            }
            wort_zahl[wort]++;
        }
    }

    // Schließen der Datei
    datei.close();

    // Anzeige der Ergebnisse
    cout << "Anzahl Vorkommen von \"" << suchwort << "\": " << anzahl << endl;
    cout << "Vorkommende Wörter:" << endl;
    for (auto &p : wort_zahl) {
        if (p.first == suchwort) {
            cout << "  " << p.first << " (x" << p.second << ")" << endl;
        }
        else {
            cout << "  " << p.first << " (x" << p.second << ")" << endl;
        }
    }

    return 0;
}
```

Das Programm liest eine Textdatei Zeile für Zeile, wobei jedes Wort in einer Hash-Struktur gespeichert wird. Die Anzahl der Vorkommen jedes Wortes wird ebenfalls in der Hash-Struktur gespeichert.

Die Anzahl der Vorkommen des gesuchten Wortes kann einfach als `anzahl` abgerufen werden. Die vollständigen Ergebnisse, einschließlich der Anzahl der Vorkommnisse jedes Wortes, werden in der Konsole angezeigt.

